// import axios from 'axios'
import axios from "axios";
import { createStore } from "vuex";

export const store = createStore({
  state() {
    return {
      api: "http://127.0.0.1:2525",
      i: 1,
      DirPath: "",
      dialogVisible: false,
      FilesTyoes: "", //获取文件类型，
      DirsFileList: [],
      uploadPercentage: 0,
      files: [],
      downZhi: "",
      OfficEword: "",
      otherDirsType: [],
      VideoPlayercontrols: true,
      ViewButtonOfficEword: "",
      upadaFileNumberSum: 0,
      ButtonAuthority: [
        { LoginButton: false },
        { LogupButton: false },
        { steeingButton: false },
        { HeadIcon: false },
        { LanShareView: false },
        { DirsFileList: false },
        { LogOutButton: false },
      ],
    };
  },
  actions: {
    async DirsFileList({ state }) {
      try {
        const res = await axios({
          url: state.api + "/DirsFileList",
          method: "post",
          params: {
            DirsFileList: state.DirPath,
          },
        });
        state.DirsFileList = Object.values(res.data.items);
        return res.data;
      } catch (err) {
        console.error("获取目录文件列表失败:", err);
        throw err;
      }
    },
    async ViewButton({ state }) {
      try {
        const res = await axios({
          url: state.api + "/fileypess",
          method: "get",
          params: {
            ViewButtonOfficEword: state.ViewButtonOfficEword,
          },
        });
        state.FilesTyoes = res.data.data;
        console.log(res.data.data);
        state.VideoPlayercontrols = true;
        state.dialogVisible = true;
        state.OfficEword = state.ViewButtonOfficEword;
        return res.data;
      } catch (err) {
        console.error("ViewButton error:", err);
        throw err;
      }
    },
    OptionDir() {
      axios({
        url: this.state.api + "/OptionDir",
        method: "post",
      }).then((res) => {
        this.state.DirPath = res.data.data;
        if (res.data.type == "成功选择目录") {
          window.location.reload();
        }
      });
    },
    async Tokers({ commit, state }) {
      try {
        const res = await axios({
          url: state.api + "/Toker",
          method: "get",
          params: {
            Time: localStorage.getItem("Time"),
            Name: localStorage.getItem("UresName"),
          },
        });

        console.log(res.data[1].message);
        let message = res.data[1].message;

        if (
          message == "登录成功" &&
          localStorage.getItem("Authority") == "Ures"
        ) {
          state.ButtonAuthority = [
            { LoginButton: false },
            { LogupButton: false },
            { steeingButton: false },
            { HeadIcon: true },
            { LanShareView: true },
            { DirsFileList: true },
            { LogOutButton: true },
          ];
        } else if (
          message == "登录成功" &&
          localStorage.getItem("Authority") == "Admin"
        ) {
          state.ButtonAuthority = [
            { LoginButton: false },
            { LogupButton: true },
            { steeingButton: true },
            { HeadIcon: true },
            { LanShareView: true },
            { DirsFileList: true },
            { LogOutButton: true },
          ];
        } else {
          localStorage.removeItem("Authority");
          localStorage.removeItem("Time");
          localStorage.removeItem("UresName");
          state.ButtonAuthority = [
            { LoginButton: true },
            { LogupButton: false },
            { steeingButton: false },
            { HeadIcon: false },
            { LanShareView: false },
            { DirsFileList: false },
            { LogOutButton: false },
          ];
          this.$router.push("/");
        }
        return message;
      } catch (err) {
        console.error("Tokers error:", err);
        throw err;
      }
    },
  },
  mutations: {
    DirsFileList(state, newDate) {
      state.DirsFileList = newDate;
    },
    ViewButtonOfficEword(state, newDate) {
      state.ViewButtonOfficEword = newDate;
      console.log(newDate);
    },
  },
});
